class CountingProposer:
    def __init__(self, *, gate: asyncio.Event | None=None, error: Exception | None=None, refuse: frozenset[str]=frozenset()): self.calls: list[list[str]] = []; self.gate = gate; self.error = error; self.refuse = refuse; self.started = asyncio.Event()
    @property
    def rows_asked(self) -> int: return sum((len(call) for call in self.calls))
    async def __call__(self, transactions, _policy):
        self.calls.append([transaction.description for transaction in transactions]); self.started.set()
        if self.gate is not None:
            try: await asyncio.wait_for(self.gate.wait(), timeout=WAIT_SECONDS)
            except TimeoutError: raise AssertionError('the test never opened the gate') from None
        if self.error is not None: raise self.error
        proposals: list[CategoryProposal | None] = []
        for transaction in transactions: kind = transaction.description.split()[0]; category, confidence = ANSWERS[kind]; proposals.append(None if kind in self.refuse else CategoryProposal(category=category.value, confidence=confidence, reason='fixture'))
        return proposals
def _install(monkeypatch, proposer: CountingProposer) -> CountingProposer: monkeypatch.setattr(transaction_classification, 'propose_categories', proposer); return proposer
def _rows(count: int, *, first_day: date=date(2026, 1, 1), kinds: list[str]=KINDS) -> list[dict]:
    rows = []
    for index in range(count): kind = kinds[index % len(kinds)]; incoming = kind in ('Salary', 'Refund'); rows.append({'description': f'{kind} {index:03d}', 'amount': (Decimal('2500.00') if incoming else Decimal('12.50')) + Decimal(index), 'direction': TransactionDirection.IN if incoming else TransactionDirection.OUT, 'date': first_day + timedelta(days=index)})
    return rows
_closing = lambda rows, opening=Decimal('1000.00'): opening + sum((row['amount'] if row['direction'] is TransactionDirection.IN else -row['amount'] for row in rows), start=Decimal('0'))
def _csv(rows: list[dict]) -> bytes:
    lines = ['Statement Currency,Date,Description,Debit Amount,Credit Amount']
    for row in rows: incoming = row['direction'] is TransactionDirection.IN; debit = '' if incoming else row['amount']; credit = row['amount'] if incoming else ''; lines.append(f"SGD,{row['date'].isoformat()},{row['description']},{debit},{credit}")
    return ('\n'.join(lines) + '\n').encode()
_sessions = lambda db: create_session_maker_from_db(db)
def _use_case(db: AsyncSession, service: ExtractionService | None=None): use_case = compose_statement_ingestion_use_case(session_maker=_sessions(db)); return replace(use_case, extraction_service_factory=lambda: service) if service is not None else use_case
_job = lambda statement_id, user_id, name, file_hash, run_id: ParseJob(statement_id=statement_id, run_id=run_id, filename=name, institution='DBS', user_id=user_id, account_id=None, file_hash=file_hash, storage_key=f'statements/{name}', model=None, request_id=f'req-{name}')
