async def _ingest_csv(db: AsyncSession, user_id: UUID, name: str, rows: list[dict]) -> UUID: content = _csv(rows); file_hash = hashlib.sha256(content).hexdigest(); statement_id = await _new_parsing_statement(db, user_id, file_hash); outcome = await _use_case(db).execute(_job(statement_id, user_id, name, file_hash, await run_for(db, statement_id)), content=content); assert outcome.status is StatementIngestionStatus.COMPLETED; return statement_id
