async def _seed(db: AsyncSession, user_id: UUID, rows: list[dict], *, name: str='seeded.pdf'):
    seeded = await seed_parsed_statement(db, user_id, institution='DBS', original_filename=name, opening_balance=Decimal('1000.00'), transactions=rows)
    if rows: seeded.statement.period_start = rows[0]['date']; seeded.statement.period_end = rows[-1]['date']
    await db.commit(); return seeded
async def _approve(client, statement_id: UUID): review = await client.get(f'/statements/{statement_id}/review'); assert review.status_code == 200, review.text; return await client.post(f'/statements/{statement_id}/review/approve', json={'create_account_if_missing': True})
