async def _read_state(client, db: AsyncSession) -> dict: balance = await client.get('/reports/balance-sheet', params={'as_of_date': '2026-03-31', 'currency': 'SGD'}); assert balance.status_code == 200, balance.text; income = await client.get('/reports/income-statement', params={'start_date': '2026-01-01', 'end_date': '2026-03-31', 'currency': 'SGD'}); assert income.status_code == 200, income.text; tokens = {str(row['id']): f"account:{row['name']}" for row in await _rows_of(db, 'accounts')}; return {'tables': await snapshot_state(db), 'reports': {'balance_sheet': _normalize(balance.json(), tokens), 'income_statement': _normalize(income.json(), tokens)}}
async def build_classified_state(client, db: AsyncSession, user_id: UUID) -> dict:
    january = _rows(len(GATE_KINDS), first_day=date(2026, 1, 1), kinds=GATE_KINDS); february = _rows(5, first_day=date(2026, 2, 10))
    for (name, rows) in (('classify_equivalence_jan.csv', january), ('classify_equivalence_feb.csv', february)): statement_id = await _ingest_csv(db, user_id, name, rows); await _confirm_csv_envelope(client, db, user_id, statement_id, rows); response = await _approve(client, statement_id); assert response.status_code == 200, response.text; assert response.json()['journal_entries_created'] == len(rows)
    return await _read_state(client, db)
async def build_review_path_state(client, db: AsyncSession, user_id: UUID) -> dict: rows = _rows(6, kinds=['Salary', 'Coffee', 'Fee', 'Mystery', 'Transfer', 'Grab']); statement_id = await _ingest_csv(db, user_id, 'classify_review_path.csv', rows); await _confirm_csv_envelope(client, db, user_id, statement_id, rows); response = await _approve(client, statement_id); assert response.status_code == 409, response.text; return await _read_state(client, db)
